"use strict";(globalThis.webpackChunkcybertrace_site=globalThis.webpackChunkcybertrace_site||[]).push([[8130],{7735(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/hashing-basics","metadata":{"permalink":"/blog/hashing-basics","editUrl":"https://github.com/defragedgaming/cybertrace.github.io/tree/main/blog/hashing-basics/hashing-basics.md","source":"@site/blog/hashing-basics/hashing-basics.md","title":"Hashing Basics","description":"Placeholder post. Content coming soon.","date":"2026-02-14T10:26:12.302Z","tags":[],"readingTime":0.03,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"Hashing Basics","slug":"/hashing-basics"},"unlisted":false,"nextItem":{"title":"Network Builder Devlog","permalink":"/blog/network-builder-devlog"}},"content":"Placeholder post. Content coming soon."},{"id":"/network-builder-devlog","metadata":{"permalink":"/blog/network-builder-devlog","editUrl":"https://github.com/defragedgaming/cybertrace.github.io/tree/main/blog/network-builder-devlog/network-builder-devlog.md","source":"@site/blog/network-builder-devlog/network-builder-devlog.md","title":"Network Builder Devlog","description":"Placeholder post. Content coming soon.","date":"2026-02-14T10:25:48.568Z","tags":[],"readingTime":0.03,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"Network Builder Devlog","slug":"/network-builder-devlog"},"unlisted":false,"prevItem":{"title":"Hashing Basics","permalink":"/blog/hashing-basics"},"nextItem":{"title":"Welcome to the CyberTrace Blog","permalink":"/blog/welcome"}},"content":"Placeholder post. Content coming soon."},{"id":"welcome","metadata":{"permalink":"/blog/welcome","editUrl":"https://github.com/defragedgaming/cybertrace.github.io/tree/main/blog/welcome/index.md","source":"@site/blog/welcome/index.md","title":"Welcome to the CyberTrace Blog","description":"The official launch of the CyberTrace blog \u2014 dev logs, security breakdowns, and behind\u2011the\u2011scenes engineering notes.","date":"2026-02-14T10:21:39.000Z","tags":[{"inline":true,"label":"intro","permalink":"/blog/tags/intro"},{"inline":true,"label":"cybertrace","permalink":"/blog/tags/cybertrace"},{"inline":true,"label":"update","permalink":"/blog/tags/update"}],"readingTime":1.33,"hasTruncateMarker":false,"authors":[{"name":"Matthew Hammel","title":"Cybersecurity Engineer & Creator of CyberTrace","imageURL":"/img/logo48x48.png","key":"defragedgaming","page":null}],"frontMatter":{"slug":"welcome","title":"Welcome to the CyberTrace Blog","authors":["defragedgaming"],"tags":["intro","cybertrace","update"],"description":"The official launch of the CyberTrace blog \u2014 dev logs, security breakdowns, and behind\u2011the\u2011scenes engineering notes."},"unlisted":false,"prevItem":{"title":"Network Builder Devlog","permalink":"/blog/network-builder-devlog"}},"content":"CyberTrace started as a personal experiment \u2014 a place to build tools I wish existed when I was learning cybersecurity.\\r\\n\\r\\nNow it\u2019s evolving into something bigger: a full ecosystem of labs, utilities, and write\u2011ups designed to make security *hands\u2011on* instead of theoretical.\\r\\n\\r\\nThis blog is where I document the process.  \\r\\nNot polished marketing. Not corporate fluff.  \\r\\nJust real engineering, real security concepts, and real progress.\\r\\n\\r\\n---\\r\\n\\r\\n## What You\u2019ll See Here\\r\\n\\r\\n**\ud83d\udd39 Dev Logs**  \\r\\nBreakdowns of how each CyberTrace tool is built \u2014 architecture, design decisions, failures, and the weird bugs that only show up at 3 AM.\\r\\n\\r\\n**\ud83d\udd39 Security Fundamentals (Explained Simply)**  \\r\\nHashing, networking, threat detection, OSINT, malware behavior \u2014 explained in a way that\u2019s actually useful, not textbook\u2011dry.\\r\\n\\r\\n**\ud83d\udd39 Platform Updates**  \\r\\nNew labs, new features, UI upgrades, performance improvements, and the occasional \u201cI broke everything and had to rebuild it\u201d moment.\\r\\n\\r\\n**\ud83d\udd39 Behind\u2011the\u2011Scenes Engineering**  \\r\\nHow the neon\u2011dark UI comes together, how the tools communicate, and how the platform stays fast without feeling cheap.\\r\\n\\r\\n---\\r\\n\\r\\n## Why CyberTrace Exists\\r\\n\\r\\nCybersecurity shouldn\u2019t feel like a locked room.  \\r\\nIt shouldn\u2019t require expensive courses or enterprise tools just to understand the basics.\\r\\n\\r\\nCyberTrace is built to be:\\r\\n\\r\\n- **accessible**  \\r\\n- **hands\u2011on**  \\r\\n- **visual**  \\r\\n- **practical**  \\r\\n- **actually fun to use**\\r\\n\\r\\nIf you want to learn security by *doing*, you\u2019re in the right place.\\r\\n\\r\\n---\\r\\n\\r\\n## What\u2019s Coming Next\\r\\n\\r\\nThe first wave of posts will cover:\\r\\n\\r\\n- The Network Builder Lab dev log  \\r\\n- Hashing fundamentals (with visuals)  \\r\\n- How the CyberTrace UI system works  \\r\\n- A breakdown of the platform roadmap  \\r\\n- The philosophy behind the Labs system  \\r\\n\\r\\nThis is just the start.  \\r\\nWelcome to the CyberTrace Blog \u2014 let\u2019s build something worth showing off."}]}}')}}]);